#!/usr/bin/env python3
"""Build the industry topical-authority library.

The source data is deliberately kept here rather than scattered through generated HTML.
Every cluster has one hub and six pages for distinct planning decisions. Re-running this
script is deterministic and replaces only files listed in ``OUTPUTS``.
"""
from __future__ import annotations

from datetime import date
from html import escape
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
HOST = "https://thebizplans.com"

# name, customers, revenue drivers, cost drivers, operating proof, compliance, funding uses
INDUSTRIES = {
    "trucking": ("Trucking", "shippers, freight brokers and contracted lanes", "loaded miles, rate per mile, utilization and fuel surcharge recovery", "tractors, trailers, fuel, insurance, repairs and driver pay", "dispatch discipline, maintenance records and safe on-time delivery", "carrier registration, safety, hours-of-service, vehicle and tax requirements", "vehicle purchases, deposits, working capital and maintenance reserves"),
    "daycare": ("Daycare", "families needing dependable age-appropriate care", "licensed spaces, enrolment, attendance, age mix and fee support", "educator payroll, occupancy, food, supplies, insurance and training", "staff-to-child ratios, retention, safeguarding and parent communication", "provincial licensing, ratios, background checks, health, fire and zoning rules", "leasehold work, play equipment, licensing costs, payroll and opening reserves"),
    "beauty-salon": ("Beauty Salon", "repeat local clients seeking hair, skin and beauty services", "appointments, service mix, average ticket, rebooking and retail attachment", "stylist labour, chair compensation, products, rent, laundry and marketing", "booking utilization, client retention, reviews and consistent service standards", "business, public-health, workplace, chemical-handling and local premises rules", "leaseholds, stations, wash units, inventory, deposits and launch marketing"),
    "nail-salon": ("Nail Salon", "local manicure, pedicure and enhancement clients", "stations, appointments, service duration, average ticket and add-ons", "technician compensation, rent, consumables, ventilation, laundry and sanitation", "station utilization, rebooking, hygiene controls and service consistency", "public-health, infection-control, ventilation, workplace and local premises rules", "ventilation, pedicure chairs, manicure stations, sterilization and working capital"),
    "grocery": ("Grocery Store", "neighbourhood households and convenience-led shoppers", "transactions, basket size, category mix, turns and shrink control", "inventory, labour, occupancy, refrigeration, spoilage, utilities and card fees", "purchasing terms, in-stock rates, cold-chain control and inventory turns", "food safety, weights and measures, tobacco or alcohol rules, zoning and employment law", "fixtures, refrigeration, point-of-sale systems, opening inventory and working capital"),
    "construction": ("Construction", "property owners, developers, general contractors and public buyers", "awarded backlog, project values, completion timing and change orders", "field labour, subcontractors, materials, equipment, bonding and holdbacks", "estimating accuracy, project controls, safety and profitable backlog conversion", "contractor licensing, permits, safety, insurance, bonding and lien requirements", "equipment, mobilization, bonding, payroll bridging and project working capital"),
    "plumbing": ("Plumbing", "homeowners, property managers, builders and commercial facilities", "billable calls, project jobs, hourly rates, material markup and memberships", "licensed labour, vehicles, parts, fuel, dispatch, insurance and callbacks", "first-time fix rates, dispatch efficiency, licensing and repeat accounts", "trade licensing, permits, codes, safety, backflow and local inspection rules", "service vans, tools, drain equipment, parts inventory and payroll reserves"),
    "hvac": ("HVAC", "homeowners, builders, property managers and commercial facilities", "service calls, installations, maintenance agreements, equipment mix and seasonality", "technician payroll, equipment, vehicles, parts, fuel, warranty work and marketing", "technician productivity, maintenance renewals, dispatch and seasonal capacity", "trade licensing, permits, refrigerant handling, codes, safety and efficiency rules", "vans, diagnostic tools, initial equipment, inventory and seasonal working capital"),
    "cannabis": ("Cannabis", "age-verified medical or adult-use customers in permitted markets", "transactions, basket size, product mix, inventory turns and repeat visits", "regulated inventory, security, compliance labour, rent, tax, shrink and testing", "traceability, responsible retailing, inventory controls and compliant customer acquisition", "federal, provincial and municipal licensing, security, packaging, promotion and age-gating", "secure leaseholds, surveillance, compliant systems, opening inventory and reserves"),
    "pharmacy": ("Pharmacy", "patients, prescribers, caregivers and local health partners", "prescription volume, dispensing fees, payer mix, clinical services and front-store sales", "pharmacist labour, drug inventory, occupancy, technology, insurance and shrink", "prescription accuracy, inventory controls, payer reconciliation and patient continuity", "college licensing, drug storage, privacy, controlled substances, records and payer requirements", "dispensary fixtures, systems, acquisition inventory, deposits and working capital"),
    "logistics": ("Logistics", "manufacturers, importers, retailers and ecommerce operators", "orders, pallets, storage days, picks, deliveries, utilization and contract pricing", "warehouse labour, occupancy, equipment, technology, transport and claims", "service-level performance, scan accuracy, capacity planning and account retention", "transport, customs, dangerous-goods, warehouse safety, privacy and trade requirements", "racking, material-handling equipment, systems, deposits and contract ramp-up capital"),
    "manufacturing": ("Manufacturing", "distributors, OEMs, retailers and direct commercial buyers", "units, selling price, yield, throughput, product mix and capacity utilization", "materials, direct labour, equipment, energy, quality, maintenance and scrap", "repeatable quality, supplier resilience, throughput and production scheduling", "product, workplace, environmental, labelling, traceability and quality requirements", "machinery, tooling, facility work, certifications, inventory and ramp-up capital"),
}

PAGE_TYPES = {
    "business-plans": ("Business Plan", "Build the complete operating and financial case"),
    "loans": ("Business Loan", "Prepare a lender-ready financing request"),
    "investors": ("Investor", "Explain the return case and capital milestones"),
    "franchises": ("Franchise", "Test the franchise economics before committing"),
    "financial-projections": ("Financial Projections", "Translate operating drivers into integrated forecasts"),
    "cost-calculator": ("Startup Cost Calculator", "Estimate startup uses and the cash buffer"),
    "pitch-decks": ("Pitch Deck", "Present a concise, evidence-led funding story"),
}

def filename(slug: str, kind: str) -> str:
    return f"{slug}-business-plans.html" if kind == "business-plans" else f"{slug}-{kind}.html"

def money_rows(name: str, uses: str) -> list[tuple[str, str, str]]:
    items = [x.strip() for x in uses.split(",")]
    return [(item.title(), "Enter supplier quote", "One-time" if i < 4 else "Opening reserve") for i, item in enumerate(items)] + [("Contingency", "5%–15% of quoted startup costs", "Do not hide this inside working capital")]

def cluster_links(slug: str, current: str = "") -> str:
    cards = []
    for kind, (label, note) in PAGE_TYPES.items():
        active = ' aria-current="page"' if kind == current else ""
        cards.append(f'<a href="{filename(slug, kind)}"{active}><strong>{escape(label)}</strong><span>{escape(note)}</span></a>')
    return "\n".join(cards)

def page_body(slug: str, kind: str, data: tuple[str, ...]) -> str:
    name, customers, revenue, costs, proof, compliance, uses = data
    if kind == "business-plans":
        return f"""<h2>What a {name.lower()} business plan must prove</h2><p>A useful plan connects a defined customer—{customers}—to an operation that can deliver consistently and make money. It should not begin with a generic market-size claim. It should show the service area, buyer problem, competitive alternative, capacity constraint and reason customers will switch or stay.</p><p>For a {name.lower()} company, the operating evidence is {proof}. The forecast then converts {revenue} into revenue and tests that result against {costs}. Each assumption should have an owner, source and review date.</p>
<h2>Recommended plan structure</h2><ol><li><strong>Executive decision summary:</strong> business stage, funding request, use of funds and measurable next milestones.</li><li><strong>Company and offer:</strong> ownership, services or products, location, pricing and differentiation.</li><li><strong>Market evidence:</strong> target segments, local demand, competitors, buying criteria and acquisition channels.</li><li><strong>Operations:</strong> workflow, capacity, suppliers, staffing, technology, quality and contingency plans.</li><li><strong>Compliance:</strong> explain responsibility and timing for {compliance}.</li><li><strong>Financial case:</strong> monthly startup forecast, annual outlook, cash needs, break-even and downside scenarios.</li></ol>
<h2>Research before writing</h2><p>Interview prospective customers, document competitor prices and service gaps, obtain written quotes for major purchases, and confirm licences with the responsible authority. Separate a verified fact from an estimate and a management target. This makes the plan updateable rather than merely persuasive.</p>
<h2>Questions the plan should answer</h2><ul class="cluster-checklist"><li>Which customer segment is served first, and why is it reachable?</li><li>What creates capacity, and what limits it?</li><li>How long is the sales or ramp-up cycle?</li><li>Which costs move with volume and which continue during a slowdown?</li><li>What cash is required before break-even?</li><li>Which licences, people or supplier relationships are on the critical path?</li></ul>"""
    if kind == "loans":
        return f"""<h2>Frame the {name.lower()} loan request</h2><p>State the amount, borrower, owner contribution, requested term and exact uses. Common uses include {uses}. Match long-lived assets to an appropriate term and identify taxes, deposits and working capital that may need separate funding.</p><h2>Show repayment capacity</h2><p>Lenders need a traceable bridge from {revenue} to gross profit, operating cash flow and debt payments. Present monthly figures through the ramp-up and seasonal cycle. Reconcile the debt schedule to the income statement, cash flow and balance sheet; adding a loan to cash without recording principal and interest is a common model error.</p><h2>Build a lender evidence file</h2><ul class="cluster-checklist"><li>Owner résumés, ownership structure and personal contribution</li><li>Supplier quotations, purchase agreements and lease terms</li><li>Licences or a dated path covering {compliance}</li><li>Contracts, letters of intent, pipeline evidence and pricing support</li><li>Historical statements and tax records for an existing business</li><li>Base, downside and delayed-start cash-flow scenarios</li></ul><h2>Stress-test the request</h2><p>Model slower sales, lower utilization, margin pressure and a delayed opening. Explain the management response: defer hiring, stage purchases, reduce owner draws, renegotiate supply or retain a larger reserve. A downside case is useful when it changes a decision, not when it simply makes every number smaller.</p>"""
    if kind == "investors":
        return f"""<h2>Define the investable proposition</h2><p>An investor plan must go beyond describing a good {name.lower()} business. Define why outside equity is appropriate, how much is being raised, the instrument being considered, the milestones the round funds and what value could exist after those milestones. Founders should obtain legal and tax advice before offering securities.</p><h2>Show a repeatable growth engine</h2><p>Connect {customers} to a measurable acquisition and retention process. The core driver model should cover {revenue}. Then explain what improves with scale and what does not: purchasing, labour productivity, site density, brand, technology, contracts or utilization.</p><h2>Investor diligence checklist</h2><ul class="cluster-checklist"><li>Cap table, founder roles and decision rights</li><li>Customer proof, pipeline quality and concentration</li><li>Unit economics and contribution margin by channel</li><li>Expansion playbook and capital required per growth unit</li><li>Key-person, compliance, supplier and execution risks</li><li>Reporting cadence, milestone budget and future capital needs</li></ul><h2>Discuss outcomes responsibly</h2><p>Do not promise returns or manufacture a valuation from an arbitrary multiple. Provide comparable context where supportable, show dilution scenarios, and explain possible strategic outcomes without presenting an exit as guaranteed. The credible story is built on {proof}.</p>"""
    if kind == "franchises":
        return f"""<h2>Evaluate the {name.lower()} franchise as a business</h2><p>A recognizable brand does not remove local-market or execution risk. Review the disclosure document with qualified legal and accounting advisers, speak with current and former franchisees, and compare their experience with the sales assumptions supplied by the franchisor.</p><h2>Rebuild the unit economics</h2><p>Start with {revenue}. Deduct {costs}, plus royalties, brand-fund contributions, mandated software, renewal costs and local marketing. Use the actual proposed territory, lease and staffing plan—not system-wide averages—to estimate cash flow.</p><h2>Franchise diligence questions</h2><ul class="cluster-checklist"><li>What is included in the initial fee and opening package?</li><li>Which suppliers, products, prices and systems are mandatory?</li><li>How are territories, online sales and new locations handled?</li><li>How many units transferred or closed, and why?</li><li>What training and opening support is documented?</li><li>What restrictions apply to renewal, transfer and exit?</li></ul><h2>Fund the full opening cycle</h2><p>The capital plan should include {uses}, franchise fees, professional fees, pre-opening payroll and contingency. Model a delayed opening and a slower sales ramp so that working capital is not mistaken for spare cash.</p>"""
    if kind == "financial-projections":
        return f"""<h2>Build the forecast from operational drivers</h2><p>Forecast {revenue}; do not type a percentage growth rate into a revenue row without operational support. Build monthly assumptions for at least the startup and first full operating year so seasonality, hiring, payment timing and capacity appear when they occur.</p><h2>Model costs and capacity</h2><p>Separate direct costs from overhead. Direct economics may change by product, job or channel, while {costs} can include both variable and fixed components. Document capacity in units that management can monitor and prevent sales from exceeding equipment, labour, space or demand constraints.</p><h2>Required schedules</h2><ul class="cluster-checklist"><li>Revenue build by material segment or channel</li><li>Direct-cost and gross-margin schedule</li><li>Headcount, compensation and payroll burden</li><li>Capital expenditures, depreciation and financing</li><li>Working capital: receivables, inventory and payables</li><li>Integrated income statement, cash flow and balance sheet</li></ul><h2>Use scenarios, not false precision</h2><p>Create a base case supported by current evidence, a downside case that combines the most material risks, and an upside case that still respects capacity. Track leading indicators tied to {proof}. Update actuals against forecast and explain price, volume, mix and timing variances.</p>"""
    if kind == "cost-calculator":
        rows = "".join(f"<tr><th scope=\"row\">{escape(a)}</th><td>{escape(b)}</td><td>{escape(c)}</td></tr>" for a,b,c in money_rows(name, uses))
        return f"""<h2>Estimate the cost to start a {name.lower()} business</h2><p>Use this worksheet as a scoping tool, not as a quoted industry average. Local rents, scale, equipment condition, financing terms and compliance choices can change the result materially. Replace every placeholder with a dated quote, written assumption or verified fee.</p><div class="table-responsive"><table class="table cluster-table"><thead><tr><th>Cost category</th><th>How to estimate</th><th>Classification</th></tr></thead><tbody>{rows}</tbody></table></div><h2>Calculate the funding requirement</h2><p><strong>Total project cost = one-time setup + opening assets + pre-opening expenses + operating cash buffer + contingency.</strong> Then subtract confirmed owner cash, assets contributed at supportable value and approved financing. Do not subtract hoped-for sales.</p><h2>Size working capital separately</h2><p>Build a monthly cash forecast using {revenue} and {costs}. Include deposits, tax timing, debt payments, owner draws and the lag between a sale and collected cash. The required buffer is driven by the lowest cumulative cash position plus a risk reserve.</p><h2>Avoid double counting</h2><ul class="cluster-checklist"><li>Separate equipment purchase from its financing payment.</li><li>Record recoverable taxes consistently.</li><li>Do not include the same opening inventory in setup and monthly cost of sales.</li><li>Distinguish contingency from ordinary working capital.</li><li>Reconcile this schedule to the balance sheet and cash-flow forecast.</li></ul>"""
    return f"""<h2>What the {name.lower()} pitch deck must accomplish</h2><p>The deck should help a specific audience understand the opportunity and decide whether to continue diligence. Keep one argument per slide, label estimates, cite material facts in slide notes and move technical detail to an appendix.</p><h2>Suggested 12-slide story</h2><ol><li>Company, purpose and funding objective</li><li>Customer problem for {customers}</li><li>Offer and customer experience</li><li>Market definition and reachable beachhead</li><li>Competition and defensible advantage</li><li>Evidence and traction</li><li>Revenue model: {revenue}</li><li>Go-to-market and retention</li><li>Operations and {proof}</li><li>Three-year financial highlights and sensitivities</li><li>Team, gaps and governance</li><li>Raise, uses, milestones and next step</li></ol><h2>Choose decision-useful metrics</h2><p>Show a small number of consistent measures—volume, utilization, average revenue, gross margin, retention, cash need and milestone progress—rather than a dashboard of vanity metrics. The deck and financial model must use the same definitions and period.</p><h2>Prepare the appendix</h2><ul class="cluster-checklist"><li>Driver-based forecast and scenario bridge</li><li>Customer, contract or pipeline evidence</li><li>Competitive comparison and source notes</li><li>Compliance path for {compliance}</li><li>Capital budget covering {uses}</li><li>Risks, mitigations and diligence contacts</li></ul>"""

def layout(title: str, description: str, canonical: str, body: str, crumbs: list[tuple[str, str]], schema: dict) -> str:
    breadcrumb = "<span aria-hidden=\"true\">/</span>".join(f'<a href="{u}">{escape(t)}</a>' if u else f'<span>{escape(t)}</span>' for t,u in crumbs)
    return f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | The Biz Plans</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{HOST}/{canonical}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{HOST}/{canonical}"><meta property="og:type" content="article"><link href="img/favicon.ico" rel="icon"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Open+Sans:wght@400;600&family=Ubuntu:wght@500;700&display=swap" rel="stylesheet"><link href="css/bootstrap.min.css" rel="stylesheet"><link href="css/style.css" rel="stylesheet"><script type="application/ld+json">{json.dumps(schema, separators=(',', ':'))}</script></head><body>
<header class="cluster-header"><div class="container-fluid sticky-top"><div class="container"><nav class="cluster-nav" aria-label="Primary"><a href="/" class="cluster-brand"><img src="img/bizplanlogo.png" width="72" height="72" loading="lazy" alt="The Biz Plans"><span>The Biz Plans</span></a><div><a href="industry-business-plans.html">Industries</a><a href="services.html">Services</a><a href="pricing.html">Pricing</a><a class="btn btn-light rounded-pill" href="project-brief.html">Start a project</a></div></nav></div></div></header>
<main><div class="container"><nav class="cluster-breadcrumb" aria-label="Breadcrumb">{breadcrumb}</nav></div>{body}</main>
<footer class="cluster-footer"><div class="container d-md-flex justify-content-between"><p>© {date.today().year} The Biz Plans. Professional business planning in Canada.</p><p><a href="editorial-policy.html">Editorial policy</a> · <a href="privacy-policy.html">Privacy</a> · <a href="contact.html">Contact</a></p></div></footer></body></html>'''

def build_page(slug: str, kind: str, data: tuple[str, ...]) -> str:
    name = data[0]; label, note = PAGE_TYPES[kind]; fn = filename(slug, kind)
    title = f"{name} {label}" if kind != "business-plans" else f"{name} Business Plans"
    desc = f"{note} for a {name.lower()} business, with industry-specific operating assumptions, evidence, risks and next steps."
    article = page_body(slug, kind, data)
    body = f'''<section class="cluster-hero"><div class="container"><p class="section-kicker">{escape(name)} planning library</p><h1>{escape(title)}</h1><p class="lead">{escape(note)} with assumptions grounded in how a {escape(name.lower())} operation actually works.</p><div class="cluster-meta"><span>Reviewed by The Biz Plans editorial team</span><span>Updated {date.today().strftime('%B %Y')}</span><span>12-minute guide</span></div></div></section><section class="cluster-content"><div class="container"><div class="row g-5"><article class="col-lg-8">{article}<aside class="cluster-note"><strong>Important:</strong> Requirements and costs vary by location and business model. Confirm current rules with the responsible regulator and obtain professional legal, tax and financing advice for your situation.</aside></article><aside class="col-lg-4"><div class="cluster-toc"><p class="section-kicker">{escape(name)} topic cluster</p><h2 class="h4">Continue your research</h2><div class="cluster-side-links">{cluster_links(slug, kind)}</div></div></aside></div><section class="cluster-next"><p class="section-kicker">From research to a decision-ready plan</p><h2>Need a plan built around your evidence?</h2><p>We develop the narrative, market research and integrated financial model for lender, investor and management review.</p><a class="btn btn-primary rounded-pill" href="project-brief.html">Request a scope assessment</a></section></div></section>'''
    schema = {"@context":"https://schema.org","@graph":[{"@type":"Article","headline":title,"description":desc,"dateModified":str(date.today()),"author":{"@type":"Organization","name":"The Biz Plans"},"publisher":{"@type":"Organization","name":"The Biz Plans"},"mainEntityOfPage":f"{HOST}/{fn}","about":{"@type":"Thing","name":f"{name} business planning"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Industries","item":f"{HOST}/industry-business-plans.html"},{"@type":"ListItem","position":2,"name":f"{name} Business Plans","item":f"{HOST}/{filename(slug, 'business-plans')}"},{"@type":"ListItem","position":3,"name":label,"item":f"{HOST}/{fn}"}]}]}
    return layout(title, desc, fn, body, [("Industries","industry-business-plans.html"),(f"{name} Business Plans",filename(slug,"business-plans") if kind != "business-plans" else ""),(label,"" )] if kind != "business-plans" else [("Industries","industry-business-plans.html"),(title,"")], schema)

def build_index() -> str:
    cards = "".join(f'''<article class="col-md-6 col-xl-4"><div class="industry-card"><p class="section-kicker">7 practical guides</p><h2 class="h3">{escape(d[0])}</h2><p>Planning resources for operations, financing, investors, franchises, projections, startup costs and pitches.</p><a href="{filename(s, 'business-plans')}">Explore the {escape(d[0].lower())} cluster <span aria-hidden="true">→</span></a></div></article>''' for s,d in INDUSTRIES.items())
    body = f'''<section class="cluster-hero"><div class="container"><p class="section-kicker">Industry expertise</p><h1>Industry Business Plan Guides</h1><p class="lead">Choose an industry to follow a complete research path—from the core business plan through funding, forecasting, costs and the pitch.</p></div></section><section class="cluster-content"><div class="container"><div class="row g-4">{cards}</div><section class="cluster-next"><h2>A growing business planning library</h2><p>These 84 guides address distinct decisions rather than swapping keywords into one generic article. Each cluster shares a clear internal-link path while keeping its operating drivers, costs, evidence and regulatory questions industry-specific.</p><a class="btn btn-primary rounded-pill" href="project-brief.html">Discuss your industry</a></section></div></section>'''
    schema={"@context":"https://schema.org","@type":"CollectionPage","name":"Industry Business Plan Guides","url":f"{HOST}/industry-business-plans.html","hasPart":[{"@type":"WebPage","name":f"{d[0]} Business Plans","url":f"{HOST}/{filename(s,'business-plans')}"} for s,d in INDUSTRIES.items()]}
    return layout("Industry Business Plan Guides", "Explore 84 practical guides across 12 industry business plan clusters, covering loans, investors, franchises, forecasts, startup costs and pitch decks.", "industry-business-plans.html", body, [("Industries","")], schema)

def update_sitemap(outputs: list[str]) -> None:
    path=ROOT/"sitemap.xml"; text=path.read_text(encoding="utf-8")
    text=re.sub(r"\n  <!-- INDUSTRY-CLUSTERS:START -->.*?<!-- INDUSTRY-CLUSTERS:END -->", "", text, flags=re.S)
    block="\n  <!-- INDUSTRY-CLUSTERS:START -->\n"+"\n".join(f"  <url><loc>{HOST}/{f}</loc></url>" for f in outputs)+"\n  <!-- INDUSTRY-CLUSTERS:END -->"
    text=text.replace("\n</urlset>",block+"\n</urlset>")
    path.write_text(text,encoding="utf-8")

def main() -> None:
    outputs=["industry-business-plans.html"]
    (ROOT/outputs[0]).write_text(build_index(),encoding="utf-8")
    for slug,data in INDUSTRIES.items():
        for kind in PAGE_TYPES:
            fn=filename(slug,kind); (ROOT/fn).write_text(build_page(slug,kind,data),encoding="utf-8"); outputs.append(fn)
    update_sitemap(outputs)
    print(f"Built {len(outputs)-1} industry guides and the library index.")

if __name__ == "__main__": main()
